class Solution {
    public long minimumRemoval(int[] beans){
        Arrays.sort(beans);
        long total=0,answer=Long.MAX_VALUE;
        for(int value:beans)total+=value;
        for(int i=0;i<beans.length;i++)answer=Math.min(answer,total-(long)(beans.length-i)*beans[i]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumRemoval(beans:IntArray):Long{
        beans.sort();
        val total=beans.sumOf{
            it.toLong()
        };
        var answer=Long.MAX_VALUE;
        for(i in beans.indices)answer=minOf(answer,total-(beans.size-i).toLong()*beans[i]);
        return answer
    }
}

